rows.vgi.executable_examples:
[
  {
    "description": "List the functions in a profile.",
    "sql": "SELECT function_id, name, filename, start_line FROM pprof.main.functions('data/go_cpu.pb.gz') WHERE error IS NULL ORDER BY function_id LIMIT 10"
  },
  {
    "description": "Which source files contribute the most symbols (functions) to a profile.",
    "sql": "SELECT filename, count(*) AS fns FROM pprof.main.functions('data/go_cpu.pb.gz') WHERE error IS NULL GROUP BY filename ORDER BY fns DESC, filename LIMIT 5"
  }
]

[
  {
    "description": "Locations with their line table (inlined frames).",
    "sql": "SELECT location_id, address, mapping_id, lines FROM pprof.main.locations('data/go_cpu.pb.gz') WHERE error IS NULL ORDER BY location_id LIMIT 10"
  },
  {
    "description": "The most heavily inlined locations (longest line table = deepest inlining the compiler folded into one address).",
    "sql": "SELECT location_id, address, len(lines) AS inline_depth FROM pprof.main.locations('data/go_cpu.pb.gz') WHERE error IS NULL ORDER BY inline_depth DESC, location_id LIMIT 5"
  }
]

[
  {
    "description": "Mappings with build ids (the addresses that still need symbolizing).",
    "sql": "SELECT mapping_id, filename, build_id FROM pprof.main.mappings('data/native.pb.gz') WHERE error IS NULL AND build_id IS NOT NULL"
  },
  {
    "description": "Every loaded binary/segment in a profile with its address range (memory_start .. memory_limit).",
    "sql": "SELECT mapping_id, filename, memory_start, memory_limit FROM pprof.main.mappings('data/go_cpu.pb.gz') WHERE error IS NULL ORDER BY mapping_id"
  }
]

[
  {
    "description": "The sample types and duration of a profile.",
    "sql": "SELECT sample_types, duration_nanos, default_sample_type FROM pprof.main.meta('data/go_heap.pb.gz') WHERE error IS NULL"
  },
  {
    "description": "The sampling period and what it counts (read this to convert raw counts to time), plus the wall-clock duration covered.",
    "sql": "SELECT period, period_type, duration_nanos FROM pprof.main.meta('data/go_cpu.pb.gz') WHERE error IS NULL"
  }
]

[
  {
    "description": "Raw samples with their leaf location id.",
    "sql": "SELECT sample_id, location_ids[1] AS leaf_loc, value FROM pprof.main.samples('data/go_cpu.pb.gz') WHERE error IS NULL"
  },
  {
    "description": "Inspect the per-sample labels (e.g. a heap profile's size_class tag) carried alongside the values.",
    "sql": "SELECT sample_id, labels, value FROM pprof.main.samples('data/alloc.pb.gz') WHERE error IS NULL LIMIT 5"
  }
]

[
  {
    "description": "Top self-time functions across a directory of CPU profiles.",
    "sql": "SELECT s.frame[1].function AS fn, sum(s.value[2]) AS cpu_ns FROM glob('/profiles/*.pb.gz') f, pprof.main.stacks(f.path) s WHERE s.error IS NULL GROUP BY 1 ORDER BY 2 DESC LIMIT 20"
  },
  {
    "description": "Flatten one profile's stacks (leaf frame, values aligned to meta.sample_types).",
    "sql": "SELECT sample_id, frame[1].function AS leaf, value FROM pprof.main.stacks('data/go_cpu.pb.gz') WHERE error IS NULL"
  }
]
